export interface ConnectorConfig {
  mailchimpApiKey: string;
  ddApiKey: string;
  ddApplicationKey: string;
  ddSite: string;
  fetch?: typeof fetch;
}

export interface MailchimpRequest {
  method: string;
  url: string;
  body?: unknown;
  headers?: Record<string, string>;
}

export interface MailchimpResponse {
  status: number;
  headers: Record<string, string>;
  body: unknown;
}

export interface HandleInput {
  originalRequest?: MailchimpRequest;
  initialResponse?: MailchimpResponse;
  finalResponse?: MailchimpResponse;
  retryCount?: number;
}

export interface HandleResult {
  eventId: string;
  retryCount: number;
  finalStatus: number;
}

async function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function getRetryAfterSeconds(headers: Record<string, string>): number {
  const retryAfter = headers['retry-after'] || headers['Retry-After'];
  if (retryAfter) {
    const seconds = parseInt(retryAfter, 10);
    if (!isNaN(seconds)) return seconds;
  }
  return 0;
}

function extractErrorMessage(body: unknown): string {
  if (!body || typeof body !== 'object') return 'Unknown error';
  const b = body as Record<string, unknown>;
  if (typeof b.detail === 'string') return b.detail;
  if (typeof b.message === 'string') return b.message;
  if (typeof b.title === 'string') return b.title;
  return JSON.stringify(body);
}

function extractTitle(body: unknown): string {
  if (!body || typeof body !== 'object') return 'Mailchimp API error';
  const b = body as Record<string, unknown>;
  if (typeof b.title === 'string') return b.title;
  if (typeof b.type === 'string') return b.type;
  return 'Mailchimp API error';
}

export async function handle(payload: HandleInput, config: ConnectorConfig): Promise<HandleResult> {
  const fetch = config.fetch ?? globalThis.fetch;
  if (!fetch) throw new Error('fetch is not available');

  if (payload.initialResponse?.status === 429 && !payload.originalRequest) {
    throw new Error('originalRequest is required when initialResponse status is 429 to perform retries');
  }

  let finalResponse: MailchimpResponse;
  let retryCount = 0;

  if (payload.finalResponse) {
    finalResponse = payload.finalResponse;
    retryCount = payload.retryCount ?? 0;
  } else if (payload.initialResponse?.status === 429 && payload.originalRequest) {
    const originalRequest = payload.originalRequest;
    let currentResponse = payload.initialResponse;
    const maxRetries = 3;

    for (let attempt = 1; attempt <= maxRetries; attempt++) {
      retryCount = attempt;
      const retryAfterSec = getRetryAfterSeconds(currentResponse.headers);
      const backoffMs = Math.pow(2, attempt) * 1000;
      const waitMs = Math.max(retryAfterSec * 1000, backoffMs);

      await sleep(waitMs);

      const retryHeaders = {
        ...originalRequest.headers,
        Authorization: `Bearer ${config.mailchimpApiKey}`,
        'Content-Type': 'application/json',
      };

      const retryResponse = await fetch(originalRequest.url, {
        method: originalRequest.method,
        headers: retryHeaders,
        body: originalRequest.body ? JSON.stringify(originalRequest.body) : undefined,
      });

      const responseBody = await retryResponse.json().catch(() => ({}));
      currentResponse = {
        status: retryResponse.status,
        headers: Object.fromEntries(retryResponse.headers.entries()),
        body: responseBody,
      };

      if (retryResponse.status !== 429) {
        break;
      }
    }
    finalResponse = currentResponse;
  } else {
    finalResponse = payload.initialResponse ?? {
      status: 0,
      headers: {},
      body: { message: 'No Mailchimp response provided' },
    };
    retryCount = payload.retryCount ?? 0;
  }

  const title = extractTitle(finalResponse.body);
  const text = extractErrorMessage(finalResponse.body);
  const dateHappened = Math.floor(Date.now() / 1000);

  const eventPayload = {
    title: `Mailchimp API 429 error after ${retryCount} retries: ${title}`,
    text: `Final error: ${text}`,
    tags: ['mailchimp', 'retry-exhausted', `retry-count:${retryCount}`],
    priority: 'normal' as const,
    source_type_name: 'Mailchimp',
    alert_type: 'error' as const,
    date_happened: dateHappened,
    category: 'change' as const,
  };

  const ddUrl = `https://event-management-intake.${config.ddSite}/api/v2/events`;
  const ddResponse = await fetch(ddUrl, {
    method: 'POST',
    headers: {
      'DD-API-KEY': config.ddApiKey,
      'DD-APPLICATION-KEY': config.ddApplicationKey,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(eventPayload),
  });

  if (!ddResponse.ok) {
    const errorBody = await ddResponse.text().catch(() => '');
    throw new Error(`Datadog API error: ${ddResponse.status} ${ddResponse.statusText} - ${errorBody}`);
  }

  const ddResult = (await ddResponse.json()) as { data?: { id?: string } };
  const eventId = ddResult.data?.id ?? 'unknown';

  return {
    eventId,
    retryCount,
    finalStatus: finalResponse.status,
  };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, HandleInput, HandleResult } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-mailchimp-key',
      ddApiKey: 'test-dd-api-key',
      ddApplicationKey: 'test-dd-app-key',
      ddSite: '{site}',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as HandleInput, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.eventId).toBe('event-12345');
  });
});

describe('handle', () => {
  it('retries up to 3 times on 429 and creates Datadog event on final failure', async () => {
    vi.useFakeTimers();
    try {
      const mailchimpUrl = 'https://us1.api.mailchimp.com/3.0/campaigns';
      const ddSite = 'us5.datadoghq.com';

      const { fetch, calls } = fakeFetch((req) => {
        if (req.url === mailchimpUrl) {
          return jsonResponse(
            { type: 'TooManyRequests', title: 'Too Many Requests', status: 429, detail: 'You have exceeded the limit', instance: 'abc' },
            429,
          );
        }
        if (req.url === `https://event-management-intake.${ddSite}/api/v2/events`) {
          return jsonResponse({ data: { id: 'event-123', type: 'event', attributes: {} } }, 201);
        }
        return jsonResponse({ error: 'not found' }, 404);
      });

      const config: ConnectorConfig = {
        mailchimpApiKey: 'test-key',
        ddApiKey: 'dd-key',
        ddApplicationKey: 'dd-app-key',
        ddSite,
        fetch,
      };

      const payload: HandleInput = {
        originalRequest: {
          method: 'POST',
          url: mailchimpUrl,
          body: { name: 'test' },
          headers: { 'Content-Type': 'application/json' },
        },
        initialResponse: {
          status: 429,
          headers: { 'retry-after': '1' },
          body: { type: 'TooManyRequests', title: 'Too Many Requests', status: 429, detail: 'You have exceeded the limit', instance: 'abc' },
        },
      };

      const promise = handle(payload, config);
      await vi.advanceTimersByTimeAsync(14000);
      const result = await promise;

      expect(result.retryCount).toBe(3);
      expect(result.finalStatus).toBe(429);
      expect(result.eventId).toBe('event-123');

      const ddCall = calls.find((c) => c.url.includes('event-management-intake'));
      expect(ddCall).toBeDefined();
      expect(ddCall!.method).toBe('POST');
      const ddJson = ddCall!.json as Record<string, unknown>;
      expect(ddJson.title).toContain('Too Many Requests');
      expect(ddJson.text).toContain('You have exceeded the limit');
      expect(ddJson.tags).toEqual(expect.arrayContaining(['mailchimp', 'retry-exhausted', 'retry-count:3']));
      expect(ddJson.alert_type).toBe('error');
      expect(ddJson.source_type_name).toBe('Mailchimp');
      expect(ddJson.category).toBe('change');
      expect(ddCall!.headers.get('DD-API-KEY')).toBe('dd-key');
      expect(ddCall!.headers.get('DD-APPLICATION-KEY')).toBe('dd-app-key');
    } finally {
      vi.useRealTimers();
    }
  });

  it('stops retrying on success and creates Datadog event', async () => {
    vi.useFakeTimers();
    try {
      const mailchimpUrl = 'https://us1.api.mailchimp.com/3.0/campaigns';
      const ddSite = 'us5.datadoghq.com';

      let attempt = 0;
      const { fetch, calls } = fakeFetch((req) => {
        if (req.url === mailchimpUrl) {
          attempt++;
          if (attempt === 1) {
            return jsonResponse({ type: 'TooManyRequests', title: 'Too Many Requests', status: 429, detail: 'Rate limited', instance: '1' }, 429);
          } else {
            return jsonResponse({ id: 'campaign-123', name: 'Test Campaign' }, 200);
          }
        }
        if (req.url === `https://event-management-intake.${ddSite}/api/v2/events`) {
          return jsonResponse({ data: { id: 'event-456', type: 'event', attributes: {} } }, 201);
        }
        return jsonResponse({ error: 'not found' }, 404);
      });

      const config: ConnectorConfig = {
        mailchimpApiKey: 'test-key',
        ddApiKey: 'dd-key',
        ddApplicationKey: 'dd-app-key',
        ddSite,
        fetch,
      };

      const payload: HandleInput = {
        originalRequest: { method: 'POST', url: mailchimpUrl, body: {} },
        initialResponse: { status: 429, headers: { 'retry-after': '1' }, body: { detail: 'Rate limited' } },
      };

      const promise = handle(payload, config);
      await vi.advanceTimersByTimeAsync(6000);
      const result = await promise;

      expect(result.retryCount).toBe(2);
      expect(result.finalStatus).toBe(200);
      expect(result.eventId).toBe('event-456');

      const ddCall = calls.find((c) => c.url.includes('event-management-intake'));
      expect(ddCall).toBeDefined();
      const ddJson = ddCall!.json as Record<string, unknown>;
      expect(ddJson.title).toContain('Campaign');
      expect(ddJson.text).toContain('Campaign');
      expect(ddJson.tags).toEqual(expect.arrayContaining(['mailchimp', 'retry-exhausted', 'retry-count:2']));
      expect(ddJson.alert_type).toBe('error');
    } finally {
      vi.useRealTimers();
    }
  });

  it('throws when initialResponse is 429 but originalRequest is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-key',
      ddApiKey: 'dd-key',
      ddApplicationKey: 'dd-app-key',
      ddSite: 'us5.datadoghq.com',
      fetch,
    };
    const payload: HandleInput = {
      initialResponse: { status: 429, headers: {}, body: {} },
    };
    await expect(handle(payload, config)).rejects.toThrow('originalRequest is required when initialResponse status is 429');
  });

  it('throws on non-2xx Datadog response', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('event-management-intake')) {
        return jsonResponse({ error: 'Unauthorized' }, 401);
      }
      return jsonResponse({}, 200);
    });
    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-key',
      ddApiKey: 'dd-key',
      ddApplicationKey: 'dd-app-key',
      ddSite: 'us5.datadoghq.com',
      fetch,
    };
    const payload: HandleInput = {
      finalResponse: { status: 429, headers: {}, body: { detail: 'test' } },
      retryCount: 3,
    };
    await expect(handle(payload, config)).rejects.toThrow('Datadog API error: 401 Unauthorized');
    expect(calls.length).toBe(1);
  });

  it('creates Datadog event directly when finalResponse provided', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('event-management-intake')) {
        return jsonResponse({ data: { id: 'event-789', type: 'event', attributes: {} } }, 201);
      }
      return jsonResponse({}, 200);
    });
    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-key',
      ddApiKey: 'dd-key',
      ddApplicationKey: 'dd-app-key',
      ddSite: 'us5.datadoghq.com',
      fetch,
    };
    const payload: HandleInput = {
      finalResponse: { status: 429, headers: {}, body: { title: 'Custom Error', detail: 'Custom detail' } },
      retryCount: 5,
    };
    const result = await handle(payload, config);
    expect(result.retryCount).toBe(5);
    expect(result.finalStatus).toBe(429);
    expect(result.eventId).toBe('event-789');
    const ddCall = calls.find((c) => c.url.includes('event-management-intake'));
    expect(ddCall).toBeDefined();
    const ddJson = ddCall!.json as Record<string, unknown>;
    expect(ddJson.title).toContain('Custom Error');
    expect(ddJson.text).toContain('Custom detail');
    expect(ddJson.tags).toEqual(expect.arrayContaining(['retry-count:5']));
  });
});

