const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

export interface ConnectorConfig {
  mailchimpApiKey: string;
  ddApiKey: string;
  ddApplicationKey: string;
  ddSite: string;
  fetch?: typeof fetch;
}

export interface MailchimpRequest {
  method: string;
  url: string;
  body?: unknown;
  headers?: Record<string, string>;
}

export interface MailchimpResponse {
  status: number;
  headers: Record<string, string>;
  body: unknown;
}

export interface HandleInput {
  originalRequest?: MailchimpRequest;
  initialResponse?: MailchimpResponse;
  finalResponse?: MailchimpResponse;
  retryCount?: number;
}

export interface HandleResult {
  eventId: string;
  retryCount: number;
  finalStatus: number;
}

async function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function getRetryAfterSeconds(headers: Record<string, string>): number {
  const retryAfter = headers['retry-after'] || headers['Retry-After'];
  if (retryAfter) {
    const seconds = parseInt(retryAfter, 10);
    if (!isNaN(seconds)) return seconds;
  }
  return 0;
}

function extractErrorMessage(body: unknown): string {
  if (!body || typeof body !== 'object') return 'Unknown error';
  const b = body as Record<string, unknown>;
  if (typeof b.detail === 'string') return b.detail;
  if (typeof b.message === 'string') return b.message;
  if (typeof b.title === 'string') return b.title;
  return JSON.stringify(body);
}

function extractTitle(body: unknown): string {
  if (!body || typeof body !== 'object') return 'Mailchimp API error';
  const b = body as Record<string, unknown>;
  if (typeof b.title === 'string') return b.title;
  if (typeof b.type === 'string') return b.type;
  if (typeof b.name === 'string') return b.name;
  return 'Mailchimp API error';
}

function headersToRecord(headers: Headers): Record<string, string> {
  const record: Record<string, string> = {};
  headers.forEach((value, key) => {
    record[key] = value;
  });
  return record;
}

export async function handle(payload: HandleInput, config: ConnectorConfig): Promise<HandleResult> {
  const fetch = config.fetch ?? globalThis.fetch;
  if (!fetch) throw new Error('fetch is not available');

  if (payload.initialResponse?.status === 429 && !payload.originalRequest) {
    throw new Error('originalRequest is required when initialResponse status is 429 to perform retries');
  }

  let finalResponse: MailchimpResponse;
  let retryCount = 0;

  if (payload.finalResponse) {
    finalResponse = payload.finalResponse;
    retryCount = payload.retryCount ?? 0;
  } else if (payload.initialResponse?.status === 429 && payload.originalRequest) {
    const originalRequest = payload.originalRequest;
    let currentResponse = payload.initialResponse;
    const maxRetries = 3;

    for (let attempt = 1; attempt <= maxRetries; attempt++) {
      retryCount = attempt;
      const retryAfterSec = getRetryAfterSeconds(currentResponse.headers);
      const backoffMs = Math.pow(2, attempt) * 1000;
      const waitMs = Math.max(retryAfterSec * 1000, backoffMs);

      await sleep(waitMs);

      const retryHeaders = {
        ...originalRequest.headers,
        Authorization: `Bearer ${config.mailchimpApiKey}`,
        'Content-Type': 'application/json',
      };

      const retryResponse = await fetch(originalRequest.url, {
        method: originalRequest.method,
        headers: retryHeaders,
        body: originalRequest.body ? JSON.stringify(originalRequest.body) : undefined,
      });

      const responseBody = await retryResponse.json().catch(() => ({}));
      currentResponse = {
        status: retryResponse.status,
        headers: headersToRecord(retryResponse.headers),
        body: responseBody,
      };

      if (retryResponse.status !== 429) {
        break;
      }
    }
    finalResponse = currentResponse;
  } else {
    finalResponse = payload.initialResponse ?? {
      status: 0,
      headers: {},
      body: { message: 'No Mailchimp response provided' },
    };
    retryCount = payload.retryCount ?? 0;
  }

  const title = extractTitle(finalResponse.body);
  const text = extractErrorMessage(finalResponse.body);
  const dateHappened = Math.floor(Date.now() / 1000);

  const eventPayload = {
    title: `Mailchimp API 429 error after ${retryCount} retries: ${title}`,
    text: `Final error: ${text}`,
    tags: ['mailchimp', 'retry-exhausted', `retry-count:${retryCount}`],
    priority: 'normal' as const,
    source_type_name: 'Mailchimp',
    alert_type: 'error' as const,
    date_happened: dateHappened,
    category: 'change' as const,
  };

  const ddUrl = `https://event-management-intake.${config.ddSite}/api/v2/events`;
  const ddResponse = await fetch(ddUrl, {
    method: 'POST',
    headers: {
      'DD-API-KEY': config.ddApiKey,
      'DD-APPLICATION-KEY': config.ddApplicationKey,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(eventPayload),
  });

  if (!ddResponse.ok) {
    const errorBody = await ddResponse.text().catch(() => '');
    throw new Error(`Datadog API error: ${ddResponse.status} ${ddResponse.statusText} - ${errorBody}`);
  }

  const ddResult = (await ddResponse.json()) as { data?: { id?: string } };
  const eventId = ddResult.data?.id ?? 'unknown';

  return {
    eventId,
    retryCount,
    finalStatus: finalResponse.status,
  };
}

